      window.__TIKTOK_WORLD_ASSETS='citizens';const npcAtlas=await Assets.load('./assets/npcs/minifolks-civilizations.json');this.npcTextures=npcAtlas.textures||npcAtlas;Object.values(this.npcTextures).forEach(texture=>texture.source.scaleMode='nearest');this.lastNpcFrame=-1;
