class TikFinityBridge extends EventTarget {
  constructor(url=(['localhost','127.0.0.1'].includes(location.hostname)?'ws://localhost:21213/':`ws://${location.hostname}:21347/`)) { super(); this.url=url; this.ws=null; this.retry=null; this.seen=new Map(); }
  connect() {
    clearTimeout(this.retry);
    try {
      this.ws = new WebSocket(this.url);
      this.ws.onopen = () => this.emit('status',{connected:true});
      this.ws.onclose = () => { this.emit('status',{connected:false}); this.retry=setTimeout(()=>this.connect(),3000); };
      this.ws.onerror = () => this.ws?.close();
      this.ws.onmessage = ({data}) => { try { this.route(JSON.parse(data)); } catch { /* ignore malformed local payloads */ } };
    } catch { this.retry=setTimeout(()=>this.connect(),3000); }
  }
  emit(type,detail){ this.dispatchEvent(new CustomEvent(type,{detail})); }
  username(data={}) { return data.uniqueId || data.user?.uniqueId || data.nickname || data.userId || 'viewer'; }
  route(packet={}) {
    const type=String(packet.event||packet.type||'').toLowerCase(); const d=packet.data||packet;
    if(type==='roomuser') return this.emit('viewers',{count:Number(d.viewerCount||d.roomUserCount||d.count)||0});
    const user=this.username(d);
    if(type==='chat') this.emit('chat',{user,text:String(d.comment||d.message||d.text||'')});
    if(type==='like') this.emit('like',{user,count:Math.max(1,Number(d.likeCount||d.count)||1)});
    if(type==='follow') this.emit('follow',{user});
    if(type==='gift') {
      const id=String(d.transactionId||d.groupId||''); const repeat=Math.max(1,Number(d.repeatCount||d.repeat_count)||1);
      let delta=repeat;
      if(id){ const previous=this.seen.get(id)||0; if(repeat<=previous) return; delta=repeat-previous; this.seen.set(id,repeat); if(this.seen.size>500) this.seen.delete(this.seen.keys().next().value); }
      if(d.giftType===1 && !d.repeatEnd && !id) return;
      this.emit('gift',{user,name:String(d.giftName||d.gift?.name||'Gift'),repeat:delta,coins:Number(d.diamondCount||d.gift?.diamond_count)||0});
    }
  }
}

const $=s=>document.querySelector(s), fmt=n=>Math.floor(n||0).toLocaleString('en-US');
async function boot(){
const bootStage=document.querySelector('#world-stage');if(!bootStage||bootStage.dataset.booted==='1')return;bootStage.dataset.booted='1';bootStage.replaceChildren();window.__TIKTOK_WORLD_BOOTING=true;
const sim=new WorldSimulation();
const renderer=new WorldRenderer(sim,$('#world-stage'));
await renderer.init();
const bridge=new TikFinityBridge();
const state={last:performance.now(),focusIndex:-1,directorAt:0,directorMode:'manual',cameraAuto:false,tip:0,selected:null,feed:[],gameSpeed:1};

class Soundscape {
  constructor(){this.ctx=null;this.master=null;this.on=true;this.music=new Audio('./assets/audio/medieval-market-loop.opus');this.music.loop=true;this.music.preload='none';this.music.volume=.23;}
  unlock(){try{const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(AudioContextClass&&!this.ctx){this.ctx=new AudioContextClass();this.master=this.ctx.createGain();this.master.gain.value=.14;this.master.connect(this.ctx.destination);}const resumed=this.ctx?.resume?.();if(resumed?.catch)resumed.catch(()=>{});}catch{}try{if(this.on&&this.music.paused)this.music.play().catch(()=>{});}catch{}}
  toggle(){this.on=!this.on;if(this.on)this.music.play().catch(()=>{});else this.music.pause();return this.on;}
  tone(freq=440,duration=.15,type='sine',gain=.12,delay=0){if(!this.ctx||!this.on)return;const t=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(55,freq*.72),t+duration);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(gain,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+duration+.02);}
  play(name,power=1){if(name==='join'){this.tone(294,.25,'triangle',.12*power);this.tone(440,.34,'triangle',.1*power,.12);this.tone(587,.45,'triangle',.08*power,.24);}else if(name==='gift'){[660,880,1100].forEach((f,i)=>this.tone(f,.28,'sine',.09*power,i*.08));}else if(name==='battle'){this.tone(95,.22,'sawtooth',.08);this.tone(62,.3,'square',.05,.13);}else this.tone(360,.16,'triangle',.07);}
}
const audio=new Soundscape();

function addFeed(icon,title,copy){state.feed.unshift({icon,title,copy});state.feed=state.feed.slice(0,7);$('#event-list').innerHTML=state.feed.map(x=>`<div class="feed-item"><b><i>${x.icon}</i>${x.title}</b><span>${x.copy}</span></div>`).join('');}
function toast(title,copy){const el=document.createElement('div');el.className='toast';el.innerHTML=`<b>${title}</b><span>${copy}</span>`;$('#toast-layer').appendChild(el);setTimeout(()=>el.remove(),2900);}
function selectKingdom(k,focus=false){if(!k)return;state.selected=k;$('#kingdom-card').classList.remove('hidden');$('#kingdom-banner').style.background=`linear-gradient(145deg,${k.color} 0 55%,${k.secondary} 55%)`;if(focus)renderer.focusKingdom(k);updateKingdomCard();}
function updateKingdomCard(){const k=state.selected;if(!k)return;if(!k.active){$('#kingdom-card').classList.add('hidden');return;}$('#kingdom-name').textContent=k.name;$('#kingdom-rank').textContent=`AGE ${k.age} · ${k.villages.length} SETTLEMENTS · ${k.buildings.length} STRUCTURES`;$('#stat-pop').textContent=fmt(k.population);$('#stat-gold').textContent=fmt(k.gold);$('#stat-food').textContent=fmt(k.food);$('#stat-army').textContent=fmt(k.army);$('#stat-land').textContent=fmt(k.land);$('#stat-fleet').textContent=fmt(k.ships);$('#stat-order').textContent=k.strategy+(k.targetUser?` → ${k.targetUser}`:'');const thresholds=[0,180,520,1200,2500],prev=thresholds[k.age-1]||0,next=thresholds[k.age]||2500;$('#era-progress').style.width=`${Math.min(100,(k.xp-prev)/(next-prev)*100)}%`;}
function updateHud(){
  const active=sim.kingdomsArray().filter(k=>k.active).sort((a,b)=>sim.power(b)-sim.power(a));$('#kingdom-count').textContent=`${active.length} KINGDOMS`;
  $('#leaderboard-list').innerHTML=active.length?active.slice(0,8).map((k,i)=>`<button type="button" class="rank-row" data-id="${k.id}" aria-label="Inspect ${k.user}"><span class="rank">${i+1}</span><span class="swatch" style="background:${k.color}"></span><span><b>${k.user}</b><small>${k.land} land · ${fmt(k.population)} pop</small></span><strong>${fmt(sim.power(k))}</strong></button>`).join(''):'<div class="empty-leaderboard">EMPTY WORLD<br><small>TYPE JOIN TO FOUND A CITY</small></div>';
  const avg=active.reduce((s,k)=>s+k.age,0)/Math.max(1,active.length);$('#age-label').textContent=['FOUNDING AGE','VILLAGE AGE','CASTLE AGE','KINGDOM AGE','DOMINION AGE'][Math.round(avg)]||'DOMINION AGE';updateKingdomCard();
}
function setDirector(title,reason){$('#focus-title').textContent=title;$('#focus-reason').textContent=reason;state.directorAt=sim.time;}
function direct(){
  const conflict=sim.conflicts[0],active=sim.kingdomsArray().filter(k=>k.active);
  if(!active.length){renderer.overview();setDirector('THE EMPTY WORLD','Waiting for the first viewer to type JOIN');state.directorMode='overview';return;}
  if(state.directorMode==='overview'){if(conflict){renderer.focusConflict(conflict);const a=sim.kingdoms.get(conflict.a),b=sim.kingdoms.get(conflict.b);setDirector(`${a.user} VS ${b.user}`,conflict.naval?'Naval battle in progress':'The frontier is burning');}else {state.focusIndex=(state.focusIndex+1)%active.length;const k=active[state.focusIndex];renderer.focusKingdom(k,1.28);setDirector(k.name,`${k.strategy} · ${k.land} land · ${fmt(k.population)} people`);}state.directorMode='focus';}
  else {renderer.overview();setDirector('THE WHOLE WORLD','Surveying every realm');state.directorMode='overview';}
}
function command(user,text,source='LIVE'){const before=sim.getByUser(user),k=sim.handleChat(user,text);if(!k)return;const cmd=String(text).trim().split(/\s+/)[0].toUpperCase();if(!before&&['JOIN','PLAY','KINGDOM'].includes(cmd)){const civ=CIVILIZATION_BY_ID[k.theme];audio.play('join');toast(`${k.user.toUpperCase()} JOINS`, `${civ.name} · ${civ.trait}`);addFeed('♜',`${k.user} founds ${civ.name}`,`${k.land} land · ${civ.trait.toLowerCase()} civilization`);setDirector(civ.name,`${source} JOIN · ${k.user}`);state.directorMode='manual';}else {audio.play('order');addFeed('◆',`${k.user}: ${k.strategy}`,k.targetUser?`Target: ${k.targetUser}`:'Royal council changes the realm strategy');}}

sim.addEventListener('defeat',e=>{const {loser,winner}=e.detail;audio.play('battle',1.5);toast(`${winner.user.toUpperCase()} CONQUERS`,`${loser.user}'s capital has fallen`);addFeed('⚔',`${loser.user} is eliminated`,`${winner.user} absorbs the defeated realm`);});
sim.addEventListener('age',e=>{const k=e.detail.kingdom;audio.play('gift');toast(`${k.user.toUpperCase()} ADVANCES`,`The realm reaches Age ${k.age}`);addFeed('✦',`${k.user} reaches Age ${k.age}`,'New architecture and economic bonuses unlocked');});
sim.addEventListener('order',e=>{if(e.detail.order==='ATTACK'||e.detail.order==='FLEET')audio.play('battle',.5);});
renderer.addEventListener('select',e=>selectKingdom(e.detail));

bridge.addEventListener('status',e=>{$('#live-dot').classList.toggle('connected',e.detail.connected);$('#bridge-label').textContent=e.detail.connected?'TIKFINITY CONNECTED':'DEMO READY';});
bridge.addEventListener('viewers',e=>{$('#viewer-count').textContent=`${fmt(e.detail.count)} VIEWERS`;});
bridge.addEventListener('chat',e=>command(e.detail.user,e.detail.text,'LIVE CHAT'));
bridge.addEventListener('like',e=>{const k=sim.like(e.detail.user,e.detail.count);if(k&&e.detail.count>=10)addFeed('♥',`${k.user} sends ${fmt(e.detail.count)} Likes`,'Workers receive extra wood and labor speed');});
bridge.addEventListener('follow',e=>{const k=sim.follow(e.detail.user);if(k){audio.play('join');addFeed('♛',`${k.user} follows`,'Permanent Royal Guard joins the kingdom');}});
bridge.addEventListener('gift',e=>{const out=sim.gift(e.detail.user,e.detail.name,e.detail.repeat,e.detail.coins);if(out){audio.play('gift',Math.min(2,1+out.gift.coins/800));toast(`${out.gift.icon} ${out.kingdom.user.toUpperCase()}`,`${out.gift.label} ×${e.detail.repeat} · ${out.gift.effect}`);addFeed(out.gift.icon,`${out.kingdom.user}: ${out.gift.label}`,out.gift.effect);}});

let worldEntered=false;
function enterWorld(event){if(event?.cancelable)event.preventDefault();if(worldEntered)return;worldEntered=true;const startScreen=$('#start-screen');startScreen.classList.add('dismissed');startScreen.setAttribute('aria-hidden','true');setTimeout(()=>{startScreen.style.display='none';},750);try{audio.unlock();}catch{}try{bridge.connect();}catch(error){console.warn('Bridge connection delayed',error);}addFeed('◎','The empty world awakens','Type JOIN in TikTok chat to found the first city');}
$('#enter-world').addEventListener('click',enterWorld);
$('#enter-world').addEventListener('touchend',enterWorld,{passive:false});
$('#speed-toggle').onclick=()=>{const speeds=[1,2,4,8],i=speeds.indexOf(state.gameSpeed);state.gameSpeed=speeds[(i+1)%speeds.length];$('#speed-toggle').textContent=`${state.gameSpeed}×`;$('#speed-toggle').title=`Simulation speed ${state.gameSpeed}×`;};
$('#sound-toggle').onclick=()=>{audio.unlock();$('#sound-toggle').textContent=audio.toggle()?'♫':'×';};
$('#overview-button').onclick=()=>{renderer.overview();state.directorMode='manual';setDirector('THE WHOLE WORLD','Vista globale manuale');};
$('#close-card').onclick=()=>$('#kingdom-card').classList.add('hidden');
$('#leaderboard-list').addEventListener('click',event=>{const row=event.target.closest('.rank-row');if(row)selectKingdom(sim.kingdoms.get(Number(row.dataset.id)),true);});
$('#dev-toggle').onclick=()=>$('#dev-body').classList.toggle('hidden');
$('#send-command').onclick=()=>command($('#test-user').value,$('#test-command').value,'LIVE TEST');
$('#test-gift').innerHTML=GIFTS.map(g=>`<option value="${g.label}">${g.icon} ${g.label} · ${g.coins} coins</option>`).join('');
document.querySelector('[data-event="like"]').onclick=()=>{const user=$('#test-user').value;kEnsure(user);const k=sim.like(user,25);if(k)addFeed('♥',`${k.user} sends 25 Likes`,'+50 wood and accelerated labor');};
document.querySelector('[data-event="follow"]').onclick=()=>{const k=sim.follow($('#test-user').value);if(k){audio.play('join');addFeed('♛',`${k.user} follows`,'Royal Guard +25');}};
document.querySelector('[data-event="gift"]').onclick=()=>{const user=$('#test-user').value;kEnsure(user);const out=sim.gift(user,$('#test-gift').value,1);if(out){audio.play('gift');toast(`${out.gift.icon} ${out.kingdom.user.toUpperCase()}`,out.gift.effect);addFeed(out.gift.icon,`${out.kingdom.user}: ${out.gift.label}`,out.gift.effect);}};
function kEnsure(user){return sim.getByUser(user)||sim.createKingdom(user,false);}

setInterval(()=>{state.tip=(state.tip+1)%TIPS.length;$('#rotating-tip').innerHTML=TIPS[state.tip];},6000);
setInterval(updateHud,500);
function loop(now){const dt=Math.min(.1,(now-state.last)/1000);state.last=now;sim.tick(dt*state.gameSpeed);$('#director-progress').style.width='0%';requestAnimationFrame(loop);}requestAnimationFrame(loop);
updateHud();setDirector(sim.kingdomsArray().some(k=>k.active)?'CAMERA MANUALE':'THE EMPTY WORLD',sim.kingdomsArray().some(k=>k.active)?'Auto camera disattivata per verifica':'Waiting for the first viewer to type JOIN');

// Intentional, explicit test API. No synthetic viewer events are generated automatically.
window.TikTokWorld={simulation:sim,renderer,chat:command,like:(u,n)=>sim.like(u,n),follow:u=>sim.follow(u),gift:(u,n,r=1)=>sim.gift(u,n,r),overview:()=>renderer.overview(),speed:n=>{state.gameSpeed=[1,2,4,8].includes(Number(n))?Number(n):1;$('#speed-toggle').textContent=`${state.gameSpeed}×`;return state.gameSpeed;}};
}
boot().catch(error=>{console.error(error);const label=document.querySelector('#bridge-label');if(label)label.textContent='STARTUP ERROR';});

